import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal
B="http://localhost:8080"
tok=None
log=[]
def get_token():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def req(path):
    global tok
    for attempt in range(200):
        if tok is None: get_token()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            log.append((path,e.code,dict(e.headers).get("Retry-After"),body))
            if e.code==404: return None
            if e.code==401: tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.05); continue
            time.sleep(0.5)
        except Exception as e:
            log.append((path,"exc",str(e),"")); time.sleep(0.5)
    raise RuntimeError(path)
orders=[]; path="/orders?page=1"
while path:
