    print(path, d["page"], d["total_pages"], len(d["items"]))
seen={}; dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DUP DIFFERS",o,seen[o["id"]])
    else: seen[o["id"]]=o
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if lo<=t.astimezone(timezone.utc)<hi: q.append(o)
cust={}
for c in {o["customer_id"] for o in q}:
    cust[c]=req("/customers/"+c)
reg={"north":0,"south":0,"east":0,"west":0}; tot=0
for o in q:
    c=cust[o["customer_id"]]
    if c is None: print("missing customer",o); continue
    a=o["amount_cents"]*(100-c["discount_pct"])
    v=(a+50)//100
    reg[c["region"]]+=v; tot+=v
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
assert sum(reg.values())==tot
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res, len(orders), len(seen))
from collections import Counter
print(Counter((l[1],l[2]) for l in log))
print(Counter(o["status"] for o in seen.values()))
print(set(type(o["amount_cents"]) for o in orders))
